/** Should this URL be served cache-first? Mirrors CACHE_FIRST_PREFIXES in
 *  scripts/build-precache.mjs — the two lists must agree or the recorded
 *  CACHE_FIRST pair guards bytes this router never pins. */
function isCacheFirstURL(url) {
  if (url.pathname.includes('/vendor/')) return true;
  if (url.pathname.includes('/textures/')) return true;
  if (url.pathname.includes('/fonts/')) return true;
  return false;
}

/**
 * Curated JSON under ./data/ — small, and edited far more often than the code
 * that reads it. These ride the APP cache, not the asset cache: a data edit
 * ships with its build and lands with it (a city label added to
 * data/cities.json used to stay invisible while data/ was cache-first and
 * pinned until CACHE_NAME changed — Ipad.md §7). Used at install only: the
 * corner stamp is the one data file allowed to be absent.
 */
function isDataURL(url) {
  return url.pathname.includes('/data/');
}

/** data/build-tag.json — gitignored in a dev tree, written by build-tag.mjs,
 *  so a 404 at install is a skip, not a failure (UpdateWatch treats it as
 *  optional too). */
